[tool error]
{
  "ok": false,
  "name": "create_alignment",
  "error": {
    "type": "invalid_params",
    "message": "[] should be non-empty (at 'elements')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1
        },
        "pis": {
          "type": "array",
          "items": {
            "type": "array",
            "items": {
              "type": "number"
            },
            "minItems": 2,
            "maxItems": 3,
            "description": "[x, y] or [x, y, radius]"
          },
          "minItems": 2
        },
        "elements": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "kind": {
                "enum": [
                  "tangent",
                  "curve"
                ]
              },
              "start": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "end": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "pc": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "pt": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "center": {
                "type": "array",
                "items": {
                  "type": "number"
                },
                "minItems": 2,
                "maxItems": 2,
                "description": "[x, y]"
              },
              "radius": {
                "type": "number",
                "exclusiveMinimum": 0
              },
              "direction": {
                "enum": [
                  "L",
                  "R"
                ]
              }
            },
            "required": [
              "kind"
            ],
            "additionalProperties": false
          },
          "minItems": 1
        },
        "begin_station": {
          "type": [
            "number",
            "string"
          ],
          "description": "display station: feet (1600) or '16+00.00'"
        },
        "equations": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "back": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "display station: feet (1600) or '16+00.00'"
              },
              "ahead": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "display station: feet (1600) or '16+00.00'"
              },
              "raw_station": {
                "type": "number"
              }
            },
            "required": [
              "back",
              "ahead"
            ],
            "additionalProperties": false
          }
        },
        "description": {
          "type": "string"
        }
      },
      "required": [
        "name"
      ],
      "additionalProperties": false
    },
    "example": {
      "name": "ALIGN-1",
      "begin_station": "10+00",
      "pis": [
        [
          1000,
          1000
        ],
        [
          1814.359354,
          1000,
          800
        ],
        [
          2433.012702,
          1357.179677
        ]
      ]
    }
  },
  "warnings": []
}

